layers.vertex:
attribute vec3 aO; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU;
    void main(){
      float u = uTime - aT; if (u < 0. || u > 1.75){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float S = 2.35; vP = position.xy*S; vU = u;
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    void main(){
      vec2 p = vP; float r = length(p), a = atan(p.x, p.y), R = 2.00, W = 1.00;
      float u = vU - W;                                            // time since impact
      float lum = 0., hot = 0.;
      // destination decal: thin ring drawn during the channel, then static until the landing (no motion, no particles)
      float draw = clamp((vU - .04)/0.37, 0., 1.), m = abs(a)/3.14159;
      float tele = step(m, draw*draw*(3. - 2.*draw) + .001);
      float ringW = u < 0. ? .012 : .012 + .02*exp(-u*10.);
      float ringI = u < 0. ? .45 : (u < .033 ? 1.4 : .45 + .6*exp(-u*6.));
      float ringFade = 1. - smoothstep(.45, .75, u);              // the rim is the last thing to go
      float ring = exp(-pow(abs(r - R)/ringW, 2.4));
      lum += ring*tele*ringI*ringFade; hot += lcore(r - R, ringW*.3)*tele*ringI*.4*ringFade;
      // decal centre: a small cross marking the exact landing point (fades in with the ring, replaced by the contact glow)
      if (u < 0.){ float cl = .32*smoothstep(.3, 1., draw);
        float cx = exp(-pow(abs(p.y)/.01, 2.))*smoothstep(cl, cl*.5, abs(p.x)) + exp(-pow(abs(p.x)/.01, 2.))*smoothstep(cl, cl*.5, abs(p.y));
        lum += cx*.4*step(.05, cl); }
      if (u >= 0.){
        // cracks: glow runs outward from the centre, then fades starting at the centre
        float front = eox(clamp(u/.18, 0., 1.))*R*.92;
        float wipe = max(u - .16, 0.)/.42*R;
        float cr = 0.;
        for (int i=0;i<9;i++){
          float fi = float(i), th = fi*.6981 + (h1(fi) - .5)*.4 + .025*sin(r*11. + fi*3.) + .015*sign(sin(r*23. + fi));   // near-straight, slightly jagged
          vec2 dir = vec2(sin(th), cos(th));
          float along = dot(p, dir), d = abs(p.x*dir.y - p.y*dir.x);
          float len = R*(.55 + .4*h1(fi + 7.));
          float w = mix(.022, .004, clamp(along/len, 0., 1.));      // thick at the centre, hair-fine at the ends
          float on = step(0., along)*smoothstep(len, len*.8, along)*smoothstep(.12, .25, along);
          cr = max(cr, exp(-pow(d/w, 2.))*on);
        }
        float lit = smoothstep(front + .05, front - .2, r) * smoothstep(wipe - .1, wipe + .4, r);
        lum += cr*lit*.55; hot += cr*lit*.12*exp(-u*7.);
        // shock ring: one thin pulse from the centre to the rim
        float rr = eox(clamp(u/.2, 0., 1.))*R, fs = 1. - clamp(u/.24, 0., 1.);
        lum += exp(-pow(abs(r - rr)/.02, 2.4))*fs*fs*.8;
        // centre: brief contact glow
        lum += exp(-r*r*6.)*(u < .033 ? 1.2 : .6*exp(-u*10.));
      }
      vec3 outc = mix(uOrange, uGold, .55)*lum + mix(uGold, vec3(1., .96, .88), .6)*hot;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }

layers.vertex:
attribute vec3 aO; attribute float aT; uniform float uTime; varying vec2 vQ; varying float vU;
    void main(){
      float u = uTime - aT - 1.00; if (u < 0. || u > .26){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float H = 1.7, Wd = .16, t = position.y*.5 + .5;
      vec3 base = aO;
      vec3 toCam = cameraPosition - base; toCam.y = 0.; vec3 side = normalize(vec3(-toCam.z, 0., toCam.x) + 1e-4);
      vQ = vec2(position.x, t); vU = u;
      gl_Position = projectionMatrix*viewMatrix*vec4(base + vec3(0., t*H, 0.) + side*position.x*Wd, 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vQ; varying float vU; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      float t = vQ.y, grow = 1. - pow(1. - clamp(vU/.06, 0., 1.), 2.);
      if (t > grow + .02) discard;
      float prof = pow(1. - t, 1.4)*smoothstep(0., .08, t);           // thickest at the ground, needle-thin at the top
      float w = .04 + .5*prof, d = abs(vQ.x);
      float band = exp(-pow(d/w, 2.4)), core = lcore(d, w*.3);
      float fade = (vU < .033 ? 1.25 : 1.)*(1. - smoothstep(.08, .26, vU))*smoothstep(grow + .02, grow - .05, t);
      vec3 outc = (mix(uOrange, uGold, .5 + .5*prof)*band*.7 + mix(uGold, vec3(1., .96, .88), .6)*core*.5)*fade*pow(prof, .5);
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }
